add_task(async function test_dialogOpenAndClose() {
  dialog.setCalendarEvent(calendarEvent);
  await dialog.show();

  Assert.ok(dialog.open, "Dialog is updated to open");
  EventUtils.synthesizeMouseAtCenter(
    dialog.querySelector(".close-button"),
    {},
    browser.contentWindow
  );
  Assert.ok(!dialog.open, "Dialog is closed");

  dialog.setCalendarEvent(calendarEvent);
  await dialog.show();
  Assert.ok(dialog.open, "Dialog is updated to open");

  // Hitting escape should call the "cancel" event on the dialog.
  const cancelEventPromise = BrowserTestUtils.waitForEvent(
    dialog,
    "cancel",
    true
  );
  EventUtils.synthesizeKey("KEY_Escape");
  await cancelEventPromise;

  Assert.ok(!dialog.open, "Dialog is closed");

async show(event) {
  await this.showPromise;

  const calendarDisplayBox = document.getElementById("calendarDisplayBox");
  const calendarDisplayBoxRect = calendarDisplayBox?.getBoundingClientRect();
  this.container =
    calendarDisplayBoxRect?.width > 0 && calendarDisplayBoxRect.height > 0
      ? calendarDisplayBox
      : (document.getElementById("tabpanelcontainer") ??
        document.documentElement);

  super.show(event);
}

close() {
  super.close();

  this.#loading = false;
  this.#reload = false;
  this.#clearData();
  this.showPromise = null;
  this.#setupShowPromise();
}
